def lfu_cache(maxsize=128, typed=False):
    cache = {}
    usage_count = {}
    def decorator(func):
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                usage_count[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                min_usage_count = min(usage_count.values())
                keys_to_remove = [k for k, v in usage_count.items() if v == min_usage_count]
                for k in keys_to_remove:
                    del cache[k]
                    del usage_count[k]
            cache[key] = result
            usage_count[key] = 1
            return result
        return wrapper
