def validate_as_prior_version(self, prior):
	if not isinstance(prior, InventoryValidator):
		return error()
	for item in prior.inventory:
		if item not in self.inventory:
			return error()
	for item in prior.inventory:
		if prior.inventory[item] > self.inventory[item]:
			return error()
	for category in prior.categories:
		if category not in self.categories:
			return error()
	for category in prior.categories:
		for subcategory in prior.categories[category]:
			if subcategory not in self.categories[category]:
				return error()
