def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict):
        return self.error("Fixity block must be a dictionary.")
    for file_path, fixity_values in fixity.items():
        if file_path not in manifest_files:
            return self.error("File {} in fixity block is not listed in the manifest.".format(file_path))
        if not isinstance(fixity_values, list):
            return self.error("Fixity values for file {} must be a list.".format(file_path))
        for fixity_value in fixity_values:
            if not isinstance(fixity_value, str):
                return self.error("Fixity value {} for file {} must be a string.".format(fixity_value, file_path))
